// Homepage 玩家群 (2026-10-16): QQ group, WeChat group (code expires every 7
// days), cloud-drive mirror. assets/community.json is the single source; the
// cards are generated by scripts/community-qr.mjs — never hand-edited.
const test = require('node:test')
const assert = require('node:assert/strict')
const { readFileSync } = require('node:fs')
const { resolve } = require('node:path')

const read = (f) => readFileSync(resolve(__dirname, '..', f), 'utf8')
const page = read('index.html')
const data = JSON.parse(read('assets/community.json'))
const block = page.slice(page.indexOf('<!-- community:start -->'), page.indexOf('<!-- community:end -->'))
const card = (k) => block.match(new RegExp(`<div class="comm-card" data-community="${k}"[\\s\\S]*?\\n        </div>`))?.[0] ?? ''

test('the generated block is there with all three cards', () => {
  assert.ok(block.length > 100, 'community block missing or empty')
  for (const k of ['qq', 'wechat', 'pan']) assert.ok(card(k), `${k} card missing`)
})

test('codes are PNG data URIs (savable to the album), not files or SVG', () => {
  const imgs = [...block.matchAll(/<img class="comm-qr" src="([^"]+)"/g)].map((m) => m[1])
  assert.equal(imgs.length, 3)
  for (const src of imgs) assert.match(src, /^data:image\/png;base64,/)
})

test('links and group number come from community.json', () => {
  assert.ok(card('qq').includes(`href="${data.qq.url}"`))
  assert.ok(card('qq').includes(data.qq.group))
  assert.ok(card('pan').includes(`href="${data.pan.url}"`))
  assert.match(data.wechat.url, /^https:\/\/weixin\.qq\.com\/g\//)
})

test('the WeChat card carries its expiry and the page hides it once past', () => {
  assert.match(data.wechat.expires, /^\d{4}-\d{2}-\d{2}$/)
  assert.ok(card('wechat').includes(`data-expires="${data.wechat.expires}T00:00:00+08:00"`))
  const [, m, d] = data.wechat.expires.split('-').map(Number)
  assert.ok(card('wechat').includes(`${m} 月 ${d} 日前有效`))
  assert.match(page, /setAttribute\('data-expired', ''\)/)
})
